#!/usr/bin/env python3
"""Rebuild compact human-guided tattoo ROIs.

The embedded polygons are a simplified representation of the user's exported
mask-editor guidance. They define WHERE tattoo extraction is allowed; they are
not production pigment masks.
"""
from pathlib import Path
import base64
import json
import zlib
import cv2
import numpy as np

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "assets" / "mask-guidance"
PACKED = ""
ROI_POLYGONS = json.loads(zlib.decompress(base64.b64decode(PACKED)).decode())

OUT.mkdir(parents=True, exist_ok=True)
for tattoo_id, polygons in ROI_POLYGONS.items():
    mask = np.zeros((640, 360), dtype=np.uint8)
    for polygon in polygons:
        cv2.fillPoly(mask, [np.asarray(polygon, dtype=np.int32)], 255)
    path = OUT / f"tattoo-{tattoo_id}.mask.png"
    if not cv2.imwrite(str(path), mask, [cv2.IMWRITE_PNG_COMPRESSION, 9]):
        raise RuntimeError(f"failed to write {path}")
    print(path)
